function startState(){let b=Array(81).fill(null),back=['L','N','S','G','K','G','S','N','L'];for(let i=0;i<9;i++){b[i]={k:back[i],o:-1};b[72+i]={k:back[8-i],o:1};b[18+i]={k:'P',o:-1};b[54+i]={k:'P',o:1}}b[10]={k:'R',o:-1};b[16]={k:'B',o:-1};b[64]={k:'B',o:1};b[70]={k:'R',o:1};return {b,h:{1:{},'-1':{}},t:1,log:[],last:null}}
function attachAudit(page,label){const audit={pageErrors:[],requestFailed:[],consoleErrors:[]};page.on('pageerror',e=>audit.pageErrors.push({label,url:page.url(),message:String(e.message||e),stack:String(e.stack||'')}));page.on('requestfailed',r=>audit.requestFailed.push({label,url:r.url(),error:String(r.failure()?.errorText||'')}));page.on('console',m=>{if(m.type()==='error')audit.consoleErrors.push({label,url:page.url(),text:m.text()})});return audit}
function assertNoUnexpected(audit,{allowConflict=false}={}){assert.deepEqual(audit.pageErrors,[]);const badReq=audit.requestFailed.filter(x=>!/Load request cancelled|NS_BINDING_ABORTED|ERR_ABORTED/i.test(x.error));assert.deepEqual(badReq,[]);const badConsole=audit.consoleErrors.filter(x=>{const t=x.text;return !/Data URL decoding failed|Load request cancelled|ERR_INVALID_URL|A ServiceWorker intercepted|COI fetch failed|favicon/i.test(t) && !(allowConflict&&/409|Conflict/i.test(t))});assert.deepEqual(badConsole,[])}
async function waitPublicApp(page,timeout=150000){const end=Date.now()+timeout;let last=null;while(Date.now()<end){try{last=await page.evaluate(()=>({url:location.href,coi:crossOriginIsolated,cards:document.querySelectorAll('#chars .ch').length,future:window.AI_SHOGI_YANEURAOU_FUTURE?.strengthTune,save:window.AI_SHOGI_SAVE?.version,cloud:window.AI_SHOGI_CLOUD_SAVE?.version,cloudBtn:!!document.getElementById('cloudSaveBtn'),pullBtn:!!document.getElementById('cloudPullBtn')}));if(last.coi&&last.cards===26&&last.future==='fullsearch-20260825'&&last.save==='21530a'&&last.cloud==='21531c'&&last.cloudBtn&&last.pullBtn)return last}catch{}await sleep(500)}throw new Error('public app timeout '+JSON.stringify(last))}
async function openPublic(page,label){await page.goto(`${BASE}/index.html?pr87finalv2=${encodeURIComponent(label)}-${Date.now()}`,{waitUntil:'domcontentloaded',timeout:120000});return waitPublicApp(page)}
async function realReplyAndSave(page){await page.locator('#chars .ch').nth(25).click();await page.selectOption('#sideSelect2157','sente');await page.click('#newBtn');await page.waitForTimeout(120);const before=(await page.locator('#moves').textContent()||'').trim();await page.locator('#board').locator(':scope > *').nth(56).click();await page.waitForTimeout(40);await page.locator('#board').locator(':scope > *').nth(47).click();await page.waitForFunction(b=>{const t=(document.getElementById('moves')?.textContent||'').trim();return t&&t!==b},before,{timeout:10000});const human=(await page.locator('#moves').textContent()||'').trim();await page.waitForFunction(h=>{const t=(document.getElementById('moves')?.textContent||'').trim(),s=(document.getElementById('status')?.textContent||'');return t!==h&&!/考えています/.test(s)},human,{timeout:120000});await page.waitForFunction(()=>window.AI_SHOGI_SAVE?.audit().savedPly>=2,null,{timeout:10000});return page.evaluate(()=>({audit:window.AI_SHOGI_SAVE.audit(),data:window.AI_SHOGI_SAVE.data(),moves:(document.getElementById('moves')?.textContent||'').trim()}))}

for(const c of cases){const browser=await c.type.launch({headless:true});const ctx=await browser.newContext({userAgent:c.ua,viewport:c.viewport});const page=await ctx.newPage();const audit=attachAudit(page,c.name);try{const first=await openPublic(page,c.name);const init=await page.evaluate(()=>({coi:crossOriginIsolated,cards:document.querySelectorAll('#chars .ch').length,unique:new Set([...document.querySelectorAll('#chars .ch')].map(x=>(x.querySelector('.chName')?.textContent||x.querySelector('img')?.alt||'').trim())).size,future:{index:window.AI_SHOGI_YANEURAOU_FUTURE.index,rating:window.AI_SHOGI_YANEURAOU_FUTURE.rating,tune:window.AI_SHOGI_YANEURAOU_FUTURE.strengthTune},cloud:window.AI_SHOGI_CLOUD_SAVE.audit(),overflow:document.documentElement.scrollWidth>innerWidth+1}));assert.equal(init.coi,true);assert.equal(init.cards,26);assert.equal(init.unique,26);assert.deepEqual(init.future,{index:25,rating:3400,tune:'fullsearch-20260825'});assert.equal(init.cloud.backend,'supabase-edge-cas-v1');assert.equal(init.cloud.buttons.cloud,true);assert.equal(init.cloud.buttons.pull,true);assert.equal(init.overflow,false);const eng=await page.evaluate(async st=>{const a=window.AI_SHOGI_YANEURAOU_FUTURE,t0=performance.now();await a.init();const r=await a.bestMove(st,{ms:300,multiPV:1,adaptive:false});return {initMs:Math.round(performance.now()-t0),status:a.status(),result:r,info:r?.info||{}}},startState());assert.equal(eng.status.ready,true);assert.equal(eng.status.worker,true);assert.equal(eng.info.hashMB,c.hash);assert.equal(eng.info.threads,1);assert.equal(eng.info.adaptive,false);assert.ok(eng.result?.move||eng.result?.resign||eng.result?.declareWin);assert.equal(await page.evaluate(()=>{window.AI_SHOGI_PIECE_SOUND.setEnabled(false);return window.AI_SHOGI_PIECE_SOUND.enabled}),false);await page.reload({waitUntil:'domcontentloaded',timeout:120000});await waitPublicApp(page);assert.equal(await page.evaluate(()=>window.AI_SHOGI_PIECE_SOUND.enabled),false);await page.evaluate(()=>window.AI_SHOGI_PIECE_SOUND.setEnabled(true));const saved=await realReplyAndSave(page);const ply=saved.audit.savedPly;assert.ok(ply>=2);assert.equal(saved.audit.savedPly,saved.audit.currentPly);assert.equal(saved.data.ci,25);await page.reload({waitUntil:'domcontentloaded',timeout:120000});await waitPublicApp(page);assert.equal((await page.evaluate(()=>window.AI_SHOGI_SAVE.audit())).savedPly,ply);assert.equal(await page.evaluate(()=>window.AI_SHOGI_SAVE.load()),true);const loaded=await page.evaluate(()=>({a:window.AI_SHOGI_SAVE.audit(),opp:(document.getElementById('oppName')?.textContent||'').trim()}));assert.equal(loaded.a.currentPly,ply);assert.equal(loaded.a.currentCharacter,25);assert.ok(loaded.opp.includes('未来からやってきたみつき'));assertNoUnexpected(audit);console.log('PR87_PUBLIC_FINAL_V2_ENV '+JSON.stringify({name:c.name,url:first.url,hash:c.hash,coi:true,cards:26,unique:26,backend:init.cloud.backend,engine:{initMs:eng.initMs,depth:eng.info.depth,nodes:eng.info.nodes,hashMB:eng.info.hashMB,threads:eng.info.threads},soundPersist:true,futureRealReply:true,savedPly:ply,reloadRestore:true,overflow:false,pageErrors:audit.pageErrors,unexpectedRequestFailures:[],unexpectedConsoleErrors:[]}))}finally{await ctx.close();await browser.close()}}

async function seedDevice(ctx,deviceId){await ctx.addInitScript(({deviceId,CLOUD})=>{localStorage.setItem('aiShogiCloudConfigV1',JSON.stringify({syncKey:'',deviceId,api:CLOUD,enabled:false}));localStorage.setItem('aiShogiCloudMetaV1',JSON.stringify({revision:0,lastSyncedSavedAt:0,pending:false,lastError:'',updatedAt:Date.now()}));localStorage.removeItem('aiShogiGameSaveV1')},{deviceId,CLOUD})}
const wb=await webkit.launch({headless:true}),cb=await chromium.launch({headless:true});const iphone=await wb.newContext({userAgent:IPHONE_UA,viewport:{width:390,height:844}}),pc=await cb.newContext({userAgent:CHROME_UA,viewport:{width:1440,height:900}});await seedDevice(iphone,'finalv2_iphone_webkit');await seedDevice(pc,'finalv2_pc_chromium');const pi=await iphone.newPage(),pp=await pc.newPage();const ia=attachAudit(pi,'IPHONE_A'),pa=attachAudit(pp,'PC_B');try{await openPublic(pi,'MIXED-IPHONE-A');const saved=await realReplyAndSave(pi);const originalPly=saved.audit.savedPly;const code=crypto.randomBytes(24).toString('base64url');assert.equal(await pi.evaluate(code=>window.AI_SHOGI_CLOUD_SAVE.enableWithCode(code),code),true);await pi.waitForFunction(()=>{const m=window.AI_SHOGI_CLOUD_SAVE.meta();return m.revision>=1&&!m.pending},null,{timeout:20000});const aRev1=await pi.evaluate(()=>window.AI_SHOGI_CLOUD_SAVE.meta().revision);
await openPublic(pp,'MIXED-PC-B');assert.equal(await pp.evaluate(code=>window.AI_SHOGI_CLOUD_SAVE.enableWithCode(code),code),true);await pp.waitForFunction(ply=>window.AI_SHOGI_SAVE?.audit().currentPly===ply,originalPly,{timeout:20000});await pp.waitForFunction(()=>!window.AI_SHOGI_CLOUD_SAVE.meta().pending,null,{timeout:20000});const pcRestored=await pp.evaluate(()=>({a:window.AI_SHOGI_SAVE.audit(),m:window.AI_SHOGI_CLOUD_SAVE.meta(),ci:window.AI_SHOGI_SAVE.data()?.ci}));assert.equal(pcRestored.a.currentPly,originalPly);assert.equal(pcRestored.ci,25);const pcBaseRev=pcRestored.m.revision;
await pp.evaluate(()=>{const x=window.AI_SHOGI_SAVE.data();x.savedAt=Date.now()+1000;x.st.log=[...(x.st.log||[]),{cloudTest:'PC-B'}];localStorage.setItem('aiShogiGameSaveV1',JSON.stringify(x));window.dispatchEvent(new Event('ai-shogi-local-save'))});await pp.waitForFunction(base=>{const m=window.AI_SHOGI_CLOUD_SAVE.meta();return m.revision>base&&!m.pending},pcBaseRev,{timeout:20000});const pcNewRev=await pp.evaluate(()=>window.AI_SHOGI_CLOUD_SAVE.meta().revision);
await pi.evaluate(()=>{const x=window.AI_SHOGI_SAVE.data();x.savedAt=Date.now()+2000;x.st.log=[...(x.st.log||[]),{cloudTest:'IPHONE-A-PENDING'}];localStorage.setItem('aiShogiGameSaveV1',JSON.stringify(x));window.dispatchEvent(new Event('ai-shogi-local-save'))});await pi.waitForFunction(()=>{const m=window.AI_SHOGI_CLOUD_SAVE.meta();return m.pending&&m.lastError==='conflict'},null,{timeout:20000});const protectedPull=await pi.evaluate(()=>window.AI_SHOGI_CLOUD_SAVE.pull());assert.equal(protectedPull.localPending,true);assert.equal(await pi.evaluate(()=>JSON.parse(localStorage.getItem('aiShogiGameSaveV1')).st.log.at(-1).cloudTest),'IPHONE-A-PENDING');pi.once('dialog',d=>d.accept());await pi.click('#cloudPullBtn');await pi.waitForFunction(()=>{const x=JSON.parse(localStorage.getItem('aiShogiGameSaveV1')||'null'),m=window.AI_SHOGI_CLOUD_SAVE.meta();return !m.pending&&x?.st?.log?.at(-1)?.cloudTest==='PC-B'},null,{timeout:20000});await sleep(1200);const finalI=await pi.evaluate(()=>({m:window.AI_SHOGI_CLOUD_SAVE.meta(),a:window.AI_SHOGI_SAVE.audit(),x:JSON.parse(localStorage.getItem('aiShogiGameSaveV1'))}));assert.ok(finalI.m.revision>=pcNewRev);assert.equal(finalI.m.pending,false);assert.equal(finalI.m.lastError,'');assert.equal(finalI.x.st.log.at(-1).cloudTest,'PC-B');assert.equal(finalI.x.ci,25);assertNoUnexpected(ia,{allowConflict:true});assertNoUnexpected(pa);console.log('PR87_PUBLIC_FINAL_V2_MIXED_DEVICE '+JSON.stringify({from:'iPhone WebKit',to:'desktop Chromium',back:'desktop Chromium to iPhone WebKit',originalPly,aInitialRevision:aRev1,pcRevisionAfterSave:pcNewRev,iphoneFinalRevision:finalI.m.revision,iphoneToPcRestore:true,conflictProtected:true,explicitDiscardRestorePcToIphone:true,pending:false,lastError:'',backend:'supabase-edge-cas-v1',iphonePageErrors:ia.pageErrors,pcPageErrors:pa.pageErrors}))}finally{await iphone.close();await pc.close();await wb.close();await cb.close()}
